extern alias RuntimeCore;
using System;using System.IO;using System.Linq;using Microsoft.CodeAnalysis;using Microsoft.CodeAnalysis.CSharp;using NUnit.Framework;
namespace FUI.Generators.Tests {public sealed class ControlInterfaceInheritanceTests {
static GeneratorDriverRunResult Run(string interfaces,string target,string property="Visible",bool command=false,string extra=""){var source="using FUI.Binding;using FUI.Rendering;[assembly:ViewModule(\"InheritanceProbe.Generated\",PropertyMode=PropertyGenerationMode.Pure)]namespace InheritanceProbe {"+interfaces+"[ViewContract(\"Probe\")]public partial class Vm:FUI.Presentation.ViewModel{[ObservableProperty][Bind(\"Target\",nameof("+target+"."+property+"))]bool value;"+(command?"[Command(\"Target\",nameof("+target+".Click))]void Run(){}":"")+extra+"}}";var platform=((string)AppContext.GetData("TRUSTED_PLATFORM_ASSEMBLIES")).Split(Path.PathSeparator).Where(p=>!Path.GetFileName(p).StartsWith("FUI."));var refs=platform.Concat(new[]{typeof(RuntimeCore::FUI.Binding.ObservableObject).Assembly.Location}).Distinct().Select(p=>MetadataReference.CreateFromFile(p));var c=CSharpCompilation.Create("InheritanceProbe",new[]{CSharpSyntaxTree.ParseText(source)},refs,new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));GeneratorDriver driver=CSharpGeneratorDriver.Create(new[]{new BindingSourceGenerator().AsSourceGenerator()});driver=driver.RunGenerators(c);return driver.GetRunResult();}
[Test]public void MultilevelControlMembersKeepRequestedControlType(){var r=Run("public interface IMiddle:IButtonElement{}public interface ILeaf:IMiddle{}","ILeaf","Interactable",true);Assert.That(r.Diagnostics.Where(d=>d.Severity==DiagnosticSeverity.Error),Is.Empty);var text=r.GeneratedTrees.Single(t=>t.FilePath.Contains("BindingInfo.g")).ToString();Assert.That(text,Does.Contain("InheritanceProbe.ILeaf"));Assert.That(text,Does.Contain("Interactable"));Assert.That(text,Does.Contain("Click"));}
[Test]public void DiamondUsesOneCommonDeclarationOnce(){var r=Run("public interface IRoot:IElement{BindableProperty<bool> Visible{get;}}public interface ILeft:IRoot{}public interface IRight:IRoot{}public interface IDiamond:ILeft,IRight{}","IDiamond");Assert.That(r.Diagnostics.Where(d=>d.Severity==DiagnosticSeverity.Error),Is.Empty);var text=r.GeneratedTrees.Single(t=>t.FilePath.Contains("BindingInfo.g")).ToString();Assert.That(text.Split(new[]{"new FUI.Infrastructure.Binding.PropertyBindingDescriptor"},StringSplitOptions.None).Length-1,Is.EqualTo(1));Assert.That(text,Does.Contain("InheritanceProbe.IDiamond"));}
[Test]public void ExplicitOwnDeclarationResolvesInheritedConflict(){var r=Run("public interface IA:IElement{BindableProperty<int> Visible{get;}}public interface IB:IElement{BindableProperty<bool> Visible{get;}}public interface IOwn:IA,IB{new BindableProperty<bool> Visible{get;}}","IOwn");Assert.That(r.Diagnostics.Where(d=>d.Severity==DiagnosticSeverity.Error),Is.Empty);Assert.That(r.GeneratedTrees.Any(t=>t.FilePath.Contains("BindingInfo.g")),Is.True);}
[TestCase("BindableProperty<int>","BindableProperty<bool>")][TestCase("BindableProperty<bool>","BindableProperty<bool>")]
public void DifferentInheritedDeclarationsReportClearConflict(string a,string b){var r=Run("public interface IA:IElement{"+a+" Visible{get;}}public interface IB:IElement{"+b+" Visible{get;}}public interface IConflict:IA,IB{}","IConflict");Assert.That(r.Diagnostics.Any(d=>d.Id=="FUI010"&&d.GetMessage().Contains("Visible")&&d.GetMessage().Contains("IConflict")),Is.True,string.Join("\n",r.Diagnostics));Assert.That(r.Diagnostics.Any(d=>d.Id=="CS8785"),Is.False);}
[Test]public void MissingInheritedMemberReportsClearDiagnosticWithoutGeneratorCrash(){var r=Run("public interface IEmpty:IElement{}","IEmpty");Assert.That(r.Diagnostics.Any(d=>d.Id=="FUI011"&&d.GetMessage().Contains("Visible")),Is.True,string.Join("\n",r.Diagnostics));Assert.That(r.Diagnostics.Any(d=>d.Id=="CS8785"),Is.False);}

[Test]public void NonObservableNestedHelperDoesNotSuppressOuterGeneration(){var r=Run("public interface IHelper:IElement{void Method();}","IVisibilityElement",extra:"public class Helper{[Bind(\"Ignored\",nameof(IHelper.Method))]bool ignored;}");Assert.That(r.Diagnostics.Where(d=>d.Severity==DiagnosticSeverity.Error),Is.Empty);Assert.That(r.GeneratedTrees.Any(t=>t.FilePath.Contains(".Vm.") && t.FilePath.Contains("BindingInfo.g")),Is.True);}
[Test]public void InvalidObservableNestedClassDoesNotSuppressValidOuter(){var r=Run("public interface IHelper:IElement{void Method();}","IVisibilityElement",extra:"public partial class Inner:FUI.Presentation.ViewModel{[ObservableProperty][Bind(\"Invalid\",nameof(IHelper.Method))]bool invalid;}");Assert.That(r.Diagnostics.Count(d=>d.Id=="FUI011"),Is.EqualTo(1));Assert.That(r.GeneratedTrees.Any(t=>t.FilePath.Contains(".Vm.") && t.FilePath.Contains("BindingInfo.g")),Is.True);Assert.That(r.GeneratedTrees.Any(t=>t.FilePath.Contains(".Inner.")),Is.False);}
[Test]public void NonObservableFieldBindingIsIgnoredLikeOriginalGenerator(){var r=Run("public interface IHelper:IElement{void Method();}","IVisibilityElement",extra:"[Bind(\"Ignored\",nameof(IHelper.Method))]bool ignored;");Assert.That(r.Diagnostics.Where(d=>d.Severity==DiagnosticSeverity.Error),Is.Empty);Assert.That(r.GeneratedTrees.Any(t=>t.FilePath.Contains(".Vm.") && t.FilePath.Contains("BindingInfo.g")),Is.True);}
}}
